# Let me take a fresh look at this
# I'll think of this as two separate rules that can both apply

def get_expected_output_dwc(grid):
    h, w = len(grid), len(grid[0])
    bg = 9  # background color
    special = 1  # dot color
    fill = 3  # fill color

    # Create copy
    out = [row[:] for row in grid]

    # Rule 1: Fill cells between 1s in a row (with multiple 1s)
    for i in range(h):
        ones = [j for j in range(w) if grid[i][j] == 1]
        if len(ones) >= 2:
            left = ones[0]
            right = ones[-1]
            for j in range(left + 1, right):
                if out[i][j] == bg:
                    out[i][j] = fill

    # Rule 2: Fill cells with 1 above and 1 below in the same column
    for j in range(w):
        for i in range(1, h - 1):
            if grid[i-1][j] == 1 and grid[i+1][j] == 1:
                if out[i][j] == bg:
                    out[i][j] = fill

    return out

