# Test the corrected rule - fill if ANY 1 above AND ANY 1 below
def get_expected_output_dwc_v2(grid):
    h, w = len(grid), len(grid[0])
    bg = 9
    special = 1
    fill = 3

    # Create copy
    out = [row[:] for row in grid]

    # Rule 1: Fill cells between 1s in a row (with multiple 1s)
    for i in range(h):
        ones = [j for j in range(w) if grid[i][j] == 1]
        if len(ones) >= 2:
            left = ones[0]
            right = ones[-1]
            for j in range(left + 1, right):
                if out[i][j] == bg:
                    out[i][j] = fill

    # Rule 2: Fill cells if there's a 1 ABOVE and a 1 BELOW in the same column
    for j in range(w):
        # Check for 1 above
        has_1_above = any(grid[r][j] == 1 for r in range(i))
        # Check for 1 below
        has_1_below = any(grid[r][j] == 1 for r in range(i + 1, h))

        for i in range(1, h - 1):
            if i < len(grid) and j < len(grid[i]):
                if has_1_above and has_1_below:
                    if out[i][j] == bg:
                        out[i][j] = fill

    return out

