# Rule: Fill ANY cell that is BETWEEN two 1s (horizontally or vertically)
def apply_horz_fill(grid):
    """Return set of (i,j) cells to fill between 1s in a row"""
    filled = set()
    h, w = len(grid), len(grid[0])
    for i in range(h):
        ones = [j for j in range(w) if grid[i][j] == 1]
        if len(ones) >= 2:
            left = ones[0]
            right = ones[-1]
            for j in range(left + 1, right):
                filled.add((i, j))
    return filled

def apply_vert_fill(grid):
    """Return set of (i,j) cells to fill between 1s in a column"""
    filled = set()
    h, w = len(grid), len(grid[0])
    for j in range(w):
        ones = [i for i in range(h) if grid[i][j] == 1]
        if len(ones) >= 2:
            top = ones[0]
            bottom = ones[-1]
            for i in range(top + 1, bottom):
                filled.add((i, j))
    return filled

def get_expected_output_dwc_final(grid):
    """Apply both horizontal and vertical fills"""
    h, w = len(grid), len(grid[0])
    bg = 9
    special = 1
    fill = 3

    out = [row[:] for row in grid]

    # Fill between 1s horizontally (and vertically)
    for (i, j) in apply_horz_fill(grid):
        if out[i][j] == bg:
            out[i][j] = fill
    for (i, j) in apply_vert_fill(grid):
        if out[i][j] == bg:
            out[i][j] = fill

    return out

# Test
